#if UNITY_EDITOR && VISTA
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using NUnit.Framework;
using UnityEditor;
using UnityEngine;

public sealed class DragonKingdomOriginalRoofProtectionTests
{
    [Serializable]sealed class RecordedField{public string source,inputSha256,outputSha256,outputFloat32;public Vector3 origin;}
    [Serializable]sealed class RecordedCase{public string name;public int actualVendorBuilds;public bool markerInputsExact;public RecordedField[] fields;}
    [Serializable]sealed class RecordedRun{public bool sameActualInputFields,originalSourcesExact,incomingContextExact,randomStateRestored;public RecordedCase[] cases;}
    static string EvidenceFile(string relative)
    {
        var args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-tsDragonRecordedRoofEvidenceRoot");Assert.That(at>=0&&at+1<args.Length,Is.True,"Explicit -tsDragonRecordedRoofEvidenceRoot <absolute existing evidence root> required; no cwd guessing or evidence regeneration");string root=args[at+1];Assert.That(Path.IsPathRooted(root)&&Directory.Exists(root),Is.True,"Recorded roof evidence root must be explicit, absolute and existing");string fullRoot=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar)+Path.DirectorySeparatorChar;string resolved=Path.GetFullPath(Path.Combine(fullRoot,relative));Assert.That(resolved.StartsWith(fullRoot,StringComparison.OrdinalIgnoreCase),Is.True,"Recorded evidence path must remain beneath its explicit root");Assert.That(File.Exists(resolved),Is.True,"Actual immutable recorded evidence missing: "+resolved);return resolved;
    }
    static Type Integration=>Type.GetType("LWS.TruckDragonKingdom.Editor.DragonKingdomRegionalWorldIntegration, Assembly-CSharp-Editor",true);
    static object Read(object value,string field)=>value.GetType().GetField(field).GetValue(value);
    static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
    static string HeightHash(float[,] values){var bytes=new byte[values.Length*4];Buffer.BlockCopy(values,0,bytes,0,bytes.Length);return Hash(bytes);}
    static float[,] Heights(byte[] bytes){Assert.That(bytes.Length,Is.EqualTo(513*513*4));var values=new float[513,513];Buffer.BlockCopy(bytes,0,values,0,bytes.Length);return values;}
    static object Invoke(float[,] observed,float[,] foundation,Vector3 origin,Bounds roof,string sdk,string expected,string expectedFoundation,string role,out float[,] output)
    {var args=new object[]{observed,foundation,origin,new Vector3(1600,600,1600),roof,sdk,expected,expectedFoundation,role,null};var proof=Integration.GetMethod("CopyOriginalUndergroundRoof",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,args);output=(float[,])args[9];return proof;}
    [TestCase("original17",0,0)][TestCase("original17",1,15)][TestCase("ownedVendorCurve",0,0)][TestCase("ownedVendorCurve",1,15)]
    public void ActualRecordedSdkRoofDamageCopiesOnlyOriginalRoofAndReportsBoundaryRisk(string name,int tile,int expectedChanges)
    {
        string receipt=EvidenceFile("Logs/TruckSports/DragonKingdom/V397/rendered-evidence/actual-owned-mountain-road-terrain.json");var receiptBytes=File.ReadAllBytes(receipt);var run=JsonUtility.FromJson<RecordedRun>(System.Text.Encoding.UTF8.GetString(receiptBytes));Assert.That(run.sameActualInputFields&&run.originalSourcesExact&&run.incomingContextExact&&run.randomStateRestored,Is.True);var actual=run.cases.Single(c=>c.name==name);Assert.That(actual.actualVendorBuilds,Is.EqualTo(1));Assert.That(actual.markerInputsExact,Is.True);var field=actual.fields[tile];string input=EvidenceFile("Logs/TruckSports/DragonKingdom/V400/rendered-evidence/owned-road-"+name+"-"+tile+".input.height.f32"),output=EvidenceFile("Logs/TruckSports/DragonKingdom/V397/rendered-evidence/owned-road-"+name+"-"+tile+".height.f32");var foundationBytes=File.ReadAllBytes(input);var sdkBytes=File.ReadAllBytes(output);Assert.That(Hash(foundationBytes),Is.EqualTo(field.inputSha256));Assert.That(Hash(sdkBytes),Is.EqualTo(field.outputSha256));var foundation=Heights(foundationBytes);var sdk=Heights(sdkBytes);var roof=new Bounds(new Vector3(560,135,780),new Vector3(400,140,260));var proof=Invoke(sdk,foundation,field.origin,roof,field.outputSha256,field.outputSha256,field.inputSha256,"ACTUAL_SDK_RAW_BEFORE_NATIVE_COORDINATOR",out var protectedField);
        foreach(string gate in new[]{"originalInputArraysExact","outsideMaskBitExact","originalRoofBitExact"})Assert.That((bool)Read(proof,gate),Is.True,gate);Assert.That((int)Read(proof,"changedRoofSamples"),Is.EqualTo(expectedChanges));Assert.That((string)Read(proof,"recordedActualSdkRawHeightSha256"),Is.EqualTo(field.outputSha256));Assert.That((string)Read(proof,"observedInputHeightSha256"),Is.EqualTo(field.outputSha256));Assert.That((string)Read(proof,"protectedCompositionHeightSha256"),Is.EqualTo(HeightHash(protectedField)));Assert.That(HeightHash(sdk),Is.EqualTo(field.outputSha256));Assert.That(HeightHash(foundation),Is.EqualTo(field.inputSha256));if(expectedChanges>0)Assert.That((string)Read(proof,"protectedCompositionHeightSha256"),Is.Not.EqualTo(field.outputSha256));TestContext.WriteLine(name+" tile="+tile+" roof="+Read(proof,"roofSamples")+" restored="+Read(proof,"changedRoofSamples")+" boundary before/after/new/worsened65="+Read(proof,"beforeBoundarySteep65")+"/"+Read(proof,"afterBoundarySteep65")+"/"+Read(proof,"newBoundarySteep65")+"/"+Read(proof,"worsenedBoundarySteep65"));Assert.That((string)Read(proof,"scope"),Does.Contain("NOT_SMOOTHING_NATIVE_COLLIDER_DIGGER_OR_FULL_WORLD_ACCEPTANCE"));CollectionAssert.AreEqual(receiptBytes,File.ReadAllBytes(receipt));CollectionAssert.AreEqual(foundationBytes,File.ReadAllBytes(input));CollectionAssert.AreEqual(sdkBytes,File.ReadAllBytes(output));
    }
    [Test,Timeout(120000)]
    public void ActualRetainedFinalFourFieldsKeepSdkReferenceDistinctWhileMeasuringOriginalRoofCopy()
    {
        var args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-tsDragonRetainedThermalSource");Assert.That(at>=0&&at+1<args.Length,Is.True,"Explicit actual native V417 source required");string receiptPath=Path.Combine(args[at+1],"rendered-evidence","regional-world-OwnedRoadRockV417.json");var bytes=File.ReadAllBytes(receiptPath);var receipt=JsonUtility.FromJson(System.Text.Encoding.UTF8.GetString(bytes),Integration.GetNestedType("Receipt"));var rows=(Array)Integration.GetMethod("QualifyRetainedThermalPhaseChain",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new[]{receipt});Assert.That(rows.Length,Is.EqualTo(4));int changed=0;
        foreach(var row in rows)
        {
            string source=(string)Read(row,"terrain"),foundationPath=(string)Read(row,"foundation");var sourceBytes=File.ReadAllBytes(source);var foundationBytes=File.ReadAllBytes(foundationPath);var data=AssetDatabase.LoadAssetAtPath<TerrainData>(source);var original=AssetDatabase.LoadAssetAtPath<TerrainData>(foundationPath);Assert.That(data.heightmapResolution,Is.EqualTo(513));Assert.That(original.heightmapResolution,Is.EqualTo(513));Assert.That(data.size,Is.EqualTo(new Vector3(1600,600,1600)));var observed=data.GetHeights(0,0,513,513);var foundation=original.GetHeights(0,0,513,513);string expected=(string)Read(row,"finalNativeHeightSha256"),sdk=(string)Read(row,"actualSdkRawHeightSha256"),foundationHash=HeightHash(foundation);Assert.That(HeightHash(observed),Is.EqualTo(expected));var proof=Invoke(observed,foundation,(Vector3)Read(row,"origin"),new Bounds(new Vector3(560,135,780),new Vector3(400,140,260)),sdk,expected,foundationHash,(string)Read(row,"sourceRole"),out var protectedField);changed+=(int)Read(proof,"changedRoofSamples");Assert.That((string)Read(proof,"recordedActualSdkRawHeightSha256"),Is.EqualTo(sdk));Assert.That((string)Read(proof,"observedInputHeightSha256"),Is.EqualTo(expected));Assert.That((bool)Read(proof,"outsideMaskBitExact")&&(bool)Read(proof,"originalRoofBitExact"),Is.True);Assert.That(HeightHash(data.GetHeights(0,0,513,513)),Is.EqualTo(expected));Assert.That(HeightHash(original.GetHeights(0,0,513,513)),Is.EqualTo(foundationHash));CollectionAssert.AreEqual(sourceBytes,File.ReadAllBytes(source));CollectionAssert.AreEqual(foundationBytes,File.ReadAllBytes(foundationPath));TestContext.WriteLine(source+" actual retained-final array-only roof protection="+JsonUtility.ToJson(proof));
        }
        Assert.That(changed,Is.GreaterThan(0),"Do not infer current all-road damage count from the older target-only15 sample");CollectionAssert.AreEqual(bytes,File.ReadAllBytes(receiptPath));
    }
    [TestCase("foundation")][TestCase("input")][TestCase("mask")][TestCase("sdkRole")][TestCase("unknownRole")]
    public void InvalidRoofFoundationInputMaskOrStageCannotBecomeASourceProtectionAuthority(string mutation)
    {
        string input=EvidenceFile("Logs/TruckSports/DragonKingdom/V400/rendered-evidence/owned-road-ownedVendorCurve-1.input.height.f32"),output=EvidenceFile("Logs/TruckSports/DragonKingdom/V397/rendered-evidence/owned-road-ownedVendorCurve-1.height.f32");var foundationBytes=File.ReadAllBytes(input);var sdkBytes=File.ReadAllBytes(output);var foundation=Heights(foundationBytes);var sdk=Heights(sdkBytes);string observed=Hash(sdkBytes),expectedFoundation=Hash(foundationBytes),recordedSdk=observed,role="ACTUAL_SDK_RAW_BEFORE_NATIVE_COORDINATOR";var roof=new Bounds(new Vector3(560,135,780),new Vector3(400,140,260));
        switch(mutation){case "foundation":foundation[34,240]+=.001f;break;case "input":sdk[34,240]+=.001f;break;case "mask":roof.center+=Vector3.right;break;case "sdkRole":recordedSdk=expectedFoundation;break;case "unknownRole":role="POST_SDK_TERRAIN_PRETENDING_TO_BE_RAW";break;default:Assert.Fail("Unknown mutation");break;}
        var failure=Assert.Throws<TargetInvocationException>(()=>Invoke(sdk,foundation,new Vector3(0,-20,800),roof,recordedSdk,observed,expectedFoundation,role,out _));Assert.That(failure.InnerException,Is.TypeOf<InvalidOperationException>());Assert.That(failure.InnerException.Message,Does.Contain("roof source protection rejected"));CollectionAssert.AreEqual(foundationBytes,File.ReadAllBytes(input));CollectionAssert.AreEqual(sdkBytes,File.ReadAllBytes(output));
    }
}
#endif
